#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package WolverineFx@4.2.0 #:package WolverineFx.Marten@4.2.0 #:package WolverineFx.RDBMS@4.2.0 #:package WolverineFx.Postgresql@4.2.0 #:package WolverineFx.FluentValidation@4.2.0 #:package WolverineFx.Http@4.2.0 #:package WolverineFx.RabbitMQ@4.2.0 #:package WolverineFx.AzureServiceBus@4.2.0 #:package WolverineFx.Http.FluentValidation@4.2.0 #:package WolverineFx.Http.Marten@4.2.0 #:package WolverineFx.AmazonSqs@4.2.0 #:package WolverineFx.EntityFrameworkCore@4.2.0 #:package WolverineFx.SqlServer@4.2.0 #:package WolverineFx.Kafka@4.2.0 #:package WolverineFx.MemoryPack@4.2.0 #:package WolverineFx.MessagePack@4.2.0 #:package WolverineFx.MQTT@4.2.0 #:package WolverineFx.Pubsub@4.2.0 #:package WolverineFx.Pulsar@4.2.0 #:package WolverineFx.RavenDb@4.2.0 #:package Microsoft.CodeAnalysis.Common@4.14.0 #:package Microsoft.CodeAnalysis.Workspaces.Common@4.14.0 #:package Swashbuckle.AspNetCore@9.0.3 #:package Swashbuckle.AspNetCore.Swagger@9.0.3 #:package Swashbuckle.AspNetCore.SwaggerGen@9.0.3 #:package Swashbuckle.AspNetCore.SwaggerUI@9.0.3 #:package Microsoft.CodeAnalysis.Analyzers@4.14.0 #:package Microsoft.CodeAnalysis.CSharp@4.14.0 #:package Mediator.Abstractions@3.0.1 #:package Mediator.SourceGenerator@3.0.1 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable #:property GenerateJsonSourceGeneration=true  using System.Buffers; using Wolverine; using Wolverine.Http; using Wolverine.RabbitMQ; using Wolverine.Kafka; using Wolverine.AzureServiceBus; using Wolverine.AmazonSqs; using Wolverine.Marten; using Wolverine.EntityFrameworkCore; using Wolverine.FluentValidation; using Marten; using Microsoft.EntityFrameworkCore; using Mediator; using Wolverine.Persistence;  //// 业务代码（可以是任何地方） // 通过 Wolverine 的 bus 发起请求，底层自动走 MediatR // var orderId = await bus.InvokeAsync<Guid>(new CreateOrder(Guid.NewGuid(), "Alice"));  // 1️⃣ 创建 HostBuilder var builder = WebApplication.CreateBuilder(args);  // 2️⃣ 注册业务仓储（示例使用内存实现） builder.Services.AddSingleton<IOrderRepository, InMemoryOrderRepository>(); builder.Services.AddSingleton<IOrderReadOnlyRepository, InMemoryOrderRepository>();  // 3️⃣ 注册 Mediator‑Core（由 SourceGenerator 生成） builder.Services.AddMediator();   // <-- Mediator.SourceGenerator 自动生成的扩展方法  // 4️⃣ 注册 Wolverine 适配器（开放式泛型） builder.Services.AddTransient(     typeof(IMessageHandler<,>),     typeof(WolverineMediatorAdapter<,>));  builder.Services.AddTransient(     typeof(IMessageHandler<>),     typeof(WolverineMediatorAdapter<>));  // 5️⃣ 配置 Wolverine builder.Host.UseWolverine(opts => {     // 让 Wolverine 扫描当前程序集（或指定多个）中的所有 Handler     opts.Discovery.IncludeType(typeof(Program).Assembly);      // 若还有“纯 Wolverine” 的 Handler（属性标记），也一起扫进来     // opts.Discovery.IncludeAssembly(typeof(SomePureWolverineHandler).Assembly);      // 也可以使用更灵活的规则，直接把所有实现 IMessageHandler<> 的类加入     opts.Discovery.IncludeTypes(t => t.CanBeCastTo(typeof(IMessageHandler<>))                                   || t.CanBeCastTo(typeof(IMessageHandler<,>)));      // ---------- 1️⃣ 注册 MediatR ----------     opts.Services.AddMediatR(typeof(Program).Assembly); // 扫描所有 MediatR handler      // ---------- 2️⃣ 为每一种 MediatR 请求类型生成适配器 ----------     // 这里使用“开放式泛型”注册，Wolverine 会在运行时为每个具体请求生成实现     opts.Services.AddTransient(typeof(IMessageHandler<,>), typeof(MediatorMessageHandlerAdapter<,>));     opts.Services.AddTransient(typeof(IMessageHandler<>), typeof(MediatorMessageHandlerAdapter<>));      // ---------- 3️⃣ 其它 Wolverine 必要配置 ----------     // 事务 / Outbox（如果业务需要）     opts.EnableOutbox();     // 示例：单进程 InMemory 传输（生产环境改为 RabbitMQ / Kafka / NATS 等）     opts.Transports.InMemory();              // 示例：同进程总线      // 开发时打开诊断日志     if (builder.Environment.IsDevelopment())         opts.EnableDiagnostics(); });  var app = builder.Build();  // ------------------------------------------------- // 示例 API（使用 Wolverine 的 IMessageBus 发起 CQRS 请求） // ------------------------------------------------- app.MapPost("/orders", async (CreateOrder cmd, IMessageBus bus) => {     // 这里的调用全部走上面的适配器 → Mediator‑Core → 业务 Handler     var orderId = await bus.InvokeAsync<Guid>(cmd);     return Results.Created($"/orders/{orderId}", new { orderId }); });  app.MapGet("/orders/{id:guid}", async (Guid id, IMessageBus bus) => {     var dto = await bus.InvokeAsync<OrderDto>(new GetOrder(id));     return dto is null ? Results.NotFound() : Results.Ok(dto); });  app.Run();  // 适配器把 MediatR 请求转发给已注册的 IMediator public class MediatorMessageHandlerAdapter<TRequest, TResponse> : IMessageHandler<TRequest, TResponse>     where TRequest : IRequest<TResponse> {     private readonly IMediator _mediator;      public MediatorMessageHandlerAdapter(IMediator mediator) => _mediator = mediator;      public async Task<TResponse> Handle(TRequest message, IMessageContext ctx)     {         // 直接把 Wolverine 的 IMessageContext 当成 MediatR 的 CancellationToken         return await _mediator.Send(message, ctx.Cancellation);     } }  // 当请求不返回值时（IRequest）对应的适配器 public class MediatorMessageHandlerAdapter<TRequest> : IMessageHandler<TRequest>     where TRequest : IRequest {     private readonly IMediator _mediator;      public MediatorMessageHandlerAdapter(IMediator mediator) => _mediator = mediator;      public async Task Handle(TRequest message, IMessageContext ctx)     {         await _mediator.Send(message, ctx.Cancellation);     } }  // MediatR =>	Wolverine 对应的写法 // IRequest<T> =>	任何 POCO（如 record CreateOrder(Guid Id, string Customer)） // IRequestHandler<T,R> =>	IMessageHandler<T,R> // mediator.Send =>	bus.InvokeAsync<TResponse>(message)  // 用属性标记让 Wolverine 自动发现（推荐） // Wolverine 通过 约定（实现 IMessageHandler<…> 接口）或 属性（[WolverineHandler]）来发现处理器。下面示例展示 属性方式——这跟在 MediatR 中标记 IRequestHandler 完全没有冲突。 // 1️⃣ Command（或者 Query）——纯 POCO（record 最简洁） public record CreateOrder(Guid OrderId, string Customer) : IMessage<Guid>;  // 2️⃣ Handler（实现 IMessageHandler<T,R>）并标记属性 [WolverineHandler]                     // ← 让 Wolverine 在启动时自动注册 public class CreateOrderHandler : IMessageHandler<CreateOrder, Guid> {     private readonly IOrderRepository _repo;      public CreateOrderHandler(IOrderRepository repo) => _repo = repo;      public async Task<Guid> Handle(CreateOrder message, IMessageContext ctx)     {         // 业务代码：写库、发领域事件……         await _repo.AddAsync(new Order { Id = message.OrderId, Customer = message.Customer });         return message.OrderId;     } }  // 业务层或 API 控制器 public async Task<Guid> BindDevice([FromBody] BindDeviceRequest req, IMessageBus bus) {     // 与 MediatR 的 Send 完全等价，只是使用了 Wolverine 的 bus     return await bus.InvokeAsync<Guid>(new CreateOrder(Guid.NewGuid(), req.Customer)); }  namespace Contracts.Commands {     // Contracts/Commands/CreateOrder.cs     using Mediator;     /// <summary>     /// 创建订单的命令。返回 OrderId (Guid) 给调用方。     /// </summary>     public sealed record CreateOrder(Guid OrderId, string Customer) : IRequest<Guid>; }  namespace Contracts.Queries {     // Contracts/Queries/GetOrder.cs     using Mediator;     /// <summary>     /// 根据订单 Id 查询订单详情。返回 OrderDto。     /// </summary>     public sealed record GetOrder(Guid OrderId) : IRequest<OrderDto>; }  namespace Application.Handlers{     // Application/Handlers/CreateOrderHandler.cs     using Mediator;     using Contracts.Commands;     using Contracts.Models;      /// <summary>     /// 业务实现：把订单写入 DB 并返回 Id。     /// </summary>     public sealed class CreateOrderHandler : IHandler<CreateOrder, Guid>     {         private readonly IOrderRepository _repo;          public CreateOrderHandler(IOrderRepository repo) => _repo = repo;          public async ValueTask<Guid> Handle(CreateOrder request, CancellationToken ct)         {             var order = new Order             {                 Id        = request.OrderId,                 Customer  = request.Customer,                 CreatedAt = DateTimeOffset.UtcNow             };              await _repo.AddAsync(order, ct);             return order.Id;         }     } }  namespace Application.Handlers {     // Application/Handlers/GetOrderHandler.cs     using Mediator;     using Contracts.Queries;     using Contracts.Models;       public sealed class GetOrderHandler : IHandler<GetOrder, OrderDto>     {         private readonly IOrderReadOnlyRepository _repo;          public GetOrderHandler(IOrderReadOnlyRepository repo) => _repo = repo;          public async ValueTask<OrderDto> Handle(GetOrder request, CancellationToken ct)         {             var order = await _repo.GetAsync(request.OrderId, ct);             return new OrderDto(order.Id, order.Customer, order.CreatedAt);         }     } }  namespace Infrastructure {     // Infrastructure/WolverineMediatorAdapter.cs     using Mediator;     using Wolverine;     using Wolverine.Runtime;     using System.Reflection;      /// <summary>     /// 当 Wolverine 收到实现了 Mediator.Abstractions.IRequest<TResponse> 的消息时，     /// 使用 DI 解析对应的 IHandler<TRequest,TResponse> 并执行。     /// </summary>     public sealed class WolverineMediatorAdapter<TRequest, TResponse> : IMessageHandler<TRequest, TResponse>         where TRequest : IRequest<TResponse>     {         private readonly IServiceProvider _provider;          public WolverineMediatorAdapter(IServiceProvider provider) => _provider = provider;          public async Task<TResponse> Handle(TRequest message, IMessageContext ctx)         {             // 通过 DI 取到对应的 Mediator Handler             var handler = _provider.GetRequiredService<IHandler<TRequest, TResponse>>();             // 直接调用 Mediator Handler（它本身返回 ValueTask<TResponse>）             return await handler.Handle(message, ctx.Cancellation);         }     }      /// <summary>     /// 对于不返回值的 IRequest（即 Mediator.Abstractions.IRequest）     /// 通过同样的方式找到 IHandler<TRequest> 并调用。     /// </summary>     public sealed class WolverineMediatorAdapter<TRequest> : IMessageHandler<TRequest>         where TRequest : IRequest     {         private readonly IServiceProvider _provider;          public WolverineMediatorAdapter(IServiceProvider provider) => _provider = provider;          public async Task Handle(TRequest message, IMessageContext ctx)         {             var handler = _provider.GetRequiredService<IHandler<TRequest>>();             await handler.Handle(message, ctx.Cancellation);         }     } }
